"""A small spreadsheet formula engine.

See README.md for the semantics. `evaluate(cells)` parses every cell, orders
them by their reference dependencies, and returns a dict of float values.
"""

import re


class CycleError(Exception):
    """Raised when cells reference each other in a cycle."""


# Longest-match-first: names before numbers doesn't matter (disjoint starts),
# but a number must swallow its decimal part in one token.
_TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<number>(?:\d+\.\d*|\.\d+|\d+))
      | (?P<name>[A-Za-z]+\d*)
      | (?P<op>[-+*/()])
    )
    """,
    re.VERBOSE,
)

_NAME_RE = re.compile(r"\A[A-Za-z]+\d*\Z")


def _tokenize(text, cell):
    """Split `text` into (kind, value) tokens. Whitespace is insignificant."""
    tokens = []
    pos = 0
    end = len(text)
    while pos < end:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            if text[pos:].strip() == "":
                break
            raise ValueError(
                "invalid character %r in cell %s" % (text[pos], cell)
            )
        pos = match.end()
        kind = match.lastgroup
        tokens.append((kind, match.group(kind)))
    return tokens


class _Parser:
    """Recursive-descent parser for the formula grammar.

    expr   := term (('+' | '-') term)*
    term   := factor (('*' | '/') factor)*
    factor := ('-' | '+') factor | atom
    atom   := number | name | '(' expr ')'
    """

    def __init__(self, tokens, cell):
        self.tokens = tokens
        self.cell = cell
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def _advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def parse(self):
        if not self.tokens:
            raise ValueError("empty formula in cell %s" % self.cell)
        node = self.parse_expr()
        if self.pos != len(self.tokens):
            raise ValueError(
                "unexpected token %r in cell %s"
                % (self.tokens[self.pos][1], self.cell)
            )
        return node

    def parse_expr(self):
        node = self.parse_term()
        while self._peek() == ("op", "+") or self._peek() == ("op", "-"):
            op = self._advance()[1]
            node = ("bin", op, node, self.parse_term())
        return node

    def parse_term(self):
        node = self.parse_factor()
        while self._peek() == ("op", "*") or self._peek() == ("op", "/"):
            op = self._advance()[1]
            node = ("bin", op, node, self.parse_factor())
        return node

    def parse_factor(self):
        kind, value = self._peek()
        if kind == "op" and value in ("-", "+"):
            self._advance()
            operand = self.parse_factor()
            return operand if value == "+" else ("neg", operand)
        return self.parse_atom()

    def parse_atom(self):
        kind, value = self._peek()
        if kind is None:
            raise ValueError("unexpected end of formula in cell %s" % self.cell)
        if kind == "number":
            self._advance()
            return ("num", float(value))
        if kind == "name":
            self._advance()
            return ("ref", value)
        if value == "(":
            self._advance()
            node = self.parse_expr()
            if self._peek() != ("op", ")"):
                raise ValueError("unbalanced '(' in cell %s" % self.cell)
            self._advance()
            return node
        raise ValueError("unexpected token %r in cell %s" % (value, self.cell))


def _parse_cell(cell, raw):
    """Parse one cell's source into an AST node."""
    if not isinstance(raw, str):
        raise ValueError("cell %s is not a string" % cell)
    text = raw.strip()
    if text.startswith("="):
        return _Parser(_tokenize(text[1:], cell), cell).parse()
    # A bare value must be a plain number, not an expression.
    try:
        return ("num", float(text))
    except ValueError:
        raise ValueError("cell %s is not a number or formula: %r" % (cell, raw))


def _refs(node, out):
    """Collect the cell names an AST node reads, depth-first."""
    stack = [node]
    while stack:
        current = stack.pop()
        tag = current[0]
        if tag == "ref":
            out.append(current[1])
        elif tag == "neg":
            stack.append(current[1])
        elif tag == "bin":
            stack.append(current[2])
            stack.append(current[3])
    return out


def _order(asts):
    """Return cell names in dependency order, raising CycleError on cycles.

    Iterative depth-first search so that long reference chains cannot exhaust
    the interpreter's recursion limit.
    """
    deps = {cell: _refs(node, []) for cell, node in asts.items()}
    for cell, names in deps.items():
        for name in names:
            if name not in asts:
                raise KeyError(
                    "cell %s references undefined cell %s" % (cell, name)
                )

    order = []
    done = set()
    on_stack = set()
    for root in asts:
        if root in done:
            continue
        # Each frame is [cell, index of the next dependency to visit].
        stack = [[root, 0]]
        on_stack.add(root)
        while stack:
            frame = stack[-1]
            cell, index = frame
            children = deps[cell]
            if index < len(children):
                frame[1] += 1
                child = children[index]
                if child in on_stack:
                    raise CycleError(
                        "cycle detected involving cell %s" % child
                    )
                if child not in done:
                    stack.append([child, 0])
                    on_stack.add(child)
            else:
                stack.pop()
                on_stack.discard(cell)
                done.add(cell)
                order.append(cell)
    return order


def _eval(node, values):
    """Evaluate an AST node; every referenced cell is already in `values`."""
    tag = node[0]
    if tag == "num":
        return node[1]
    if tag == "ref":
        return values[node[1]]
    if tag == "neg":
        return -_eval(node[1], values)
    op, left, right = node[1], _eval(node[2], values), _eval(node[3], values)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    return left / right  # ZeroDivisionError propagates, per the spec.


def evaluate(cells):
    """Compute every cell's value.

    Returns a dict mapping each cell name to a float. Raises CycleError if any
    cell reaches itself through references, and ZeroDivisionError on division
    by zero.
    """
    asts = {}
    for cell, raw in cells.items():
        if not _NAME_RE.match(cell):
            raise ValueError("invalid cell name %r" % (cell,))
        asts[cell] = _parse_cell(cell, raw)

    values = {}
    for cell in _order(asts):
        values[cell] = _eval(asts[cell], values)
    return values

